/**
 * L3 — Price Guard
 *
 * Validates payment amounts against:
 *  1. The registry's price band (minAtomic ≤ amount ≤ maxAtomic)
 *  2. Price-rise detection (amount > last quote for same endpoint)
 *  3. Approval threshold — requires a cryptographic one-time token
 *     (fixes G15: approvalRef was any non-empty string)
 *
 * All amounts are handled as BigInt atomic units.
 * Never converts via Number(x)/1e6 (fixes G12).
 *
 * Approval tokens:
 *  - Generated by a supervisor/human with knowledge of SIGNING_SECRET
 *  - Format: HMAC-SHA256("approve:<amountAtomic>:<merchantHost>:<nonce>")
 *  - Single-use: consumed from the token store on first use
 */

import { createHash, createHmac } from "node:crypto";
import { signingSecret } from "../sign.js";
import { REASON } from "./reasons.js";
import type { EndpointRegistryEntry } from "./registry.js";

export interface PriceCheckResult {
  allowed: boolean;
  reason: string;
  detail?: string;
}

/** In-memory store for recent quotes per endpoint (prevents price-rise attack A3) */
const _lastQuote = new Map<string, bigint>();

/** One-time approval token store */
const _usedTokens = new Set<string>();

function endpointKey(entry: EndpointRegistryEntry): string {
  return `${entry.origin}|${entry.method}|${entry.path}`;
}

/**
 * Check if an atomic amount is within the registry's price band
 * and hasn't risen from the last quoted price.
 * Amounts are BigInt — no float conversions.
 */
export function checkPrice(
  amountAtomic: string,
  entry: EndpointRegistryEntry,
  approvalRef?: string
): PriceCheckResult {
  let amount: bigint;
  try {
    amount = BigInt(amountAtomic);
  } catch {
    return {
      allowed: false,
      reason: REASON.L3_PRICE_OUT_OF_BAND,
      detail: `Cannot parse amount as BigInt: ${amountAtomic}`,
    };
  }

  const min = BigInt(entry.price.minAtomic);
  const max = BigInt(entry.price.maxAtomic);

  // Price band check
  if (amount < min || amount > max) {
    return {
      allowed: false,
      reason: REASON.L3_PRICE_OUT_OF_BAND,
      detail: `Amount ${amountAtomic} outside band [${entry.price.minAtomic}, ${entry.price.maxAtomic}]`,
    };
  }

  // Price-rise detection (A3 fix)
  const key = endpointKey(entry);
  const last = _lastQuote.get(key);
  if (last !== undefined && amount > last) {
    return {
      allowed: false,
      reason: REASON.L3_PRICE_RISE,
      detail: `Amount ${amountAtomic} rose from last quote ${last.toString()}`,
    };
  }

  // Check approval threshold if configured
  // For the hackathon, threshold = maxAtomic * 0.5 (50% of max)
  // In production, this would come from the policy config
  const approvalThreshold = (max * 50n) / 100n;
  if (amount >= approvalThreshold) {
    if (!approvalRef) {
      return {
        allowed: false,
        reason: REASON.L3_APPROVAL_REQUIRED,
        detail: `Amount ${amountAtomic} >= approval threshold ${approvalThreshold.toString()}; supply approvalRef token`,
      };
    }
    // Validate the approval token cryptographically (G15 fix)
    if (!validateApprovalToken(approvalRef, amountAtomic, entry)) {
      return {
        allowed: false,
        reason: REASON.L3_APPROVAL_TOKEN_INVALID,
        detail: "approvalRef token is invalid or already used",
      };
    }
  }

  // Record this quote for price-rise detection
  _lastQuote.set(key, amount);

  return { allowed: true, reason: REASON.ALLOW };
}

/**
 * Generate a one-time approval token for a spend.
 * Used by a supervisor/human to pre-authorize a large payment.
 *
 * Token = HMAC-SHA256(secret, "approve:<amount>:<origin>:<method>:<path>:<nonce>")
 * where nonce = random hex
 */
export function generateApprovalToken(
  amountAtomic: string,
  entry: EndpointRegistryEntry,
  nonce?: string
): { token: string; nonce: string } {
  const n = nonce ?? createHash("sha256").update(Math.random().toString()).digest("hex").slice(0, 16);
  const message = `approve:${amountAtomic}:${entry.origin}:${entry.method}:${entry.path}:${n}`;
  const token = createHmac("sha256", signingSecret()).update(message).digest("hex");
  return { token: `${n}.${token}`, nonce: n };
}

/**
 * Validate and consume a one-time approval token.
 * Returns false if invalid or already used.
 */
function validateApprovalToken(
  approvalRef: string,
  amountAtomic: string,
  entry: EndpointRegistryEntry
): boolean {
  const parts = approvalRef.split(".");
  if (parts.length !== 2) return false;
  const [nonce, tokenHex] = parts;

  const message = `approve:${amountAtomic}:${entry.origin}:${entry.method}:${entry.path}:${nonce}`;
  const expected = createHmac("sha256", signingSecret()).update(message).digest("hex");

  // Timing-safe comparison
  if (
    tokenHex.length !== expected.length ||
    !timingSafeEqual(tokenHex, expected)
  ) {
    return false;
  }

  // Single-use: reject if already consumed
  if (_usedTokens.has(approvalRef)) return false;
  _usedTokens.add(approvalRef);

  return true;
}

function timingSafeEqual(a: string, b: string): boolean {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) {
    diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  }
  return diff === 0;
}

/** Reset quote history (for testing) */
export function _resetQuoteHistory(): void {
  _lastQuote.clear();
  _usedTokens.clear();
}
